import * as Rules from './rules.js';
import {loadArt,drawTerrain,drawBuilding,drawIcon} from './art.js';
import {readSave,writeSave,replaceSave,SAVE_KEY} from './storage.js';
const {TERRAIN,BUILDINGS,createGame,rotateCells,canPlaceLand,placeLand,build,upgrade,demolish,reroll,setPolicy,nextTurn,forecast,validateSave}=Rules;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const signed=n=>(n>0?'+':'')+Math.round(n), seasonNames=['春','夏','秋','冬'];
let storage,loaded;try{storage=window.localStorage;loaded=readSave(storage);}catch{loaded={ok:false,reason:'浏览器未允许本地存档'};}
let state=loaded.ok&&loaded.state?loaded.state:createGame(20261019), tab='land', selection=null, selectedTile=null, rotation=0, anchor=null, cell=matchMedia('(max-height:700px) and (orientation:portrait)').matches?48:64, toastTimer, unsaved=false, blocked=!loaded.ok;
const board=$('#board'),viewport=$('#viewport'),panel=$('#panel'),dialog=$('#dialog');
board.style.setProperty('--cell',cell+'px');
const tileEls=[];
for(let y=0;y<14;y++)for(let x=0;x<14;x++){const el=document.createElement('button');el.className='tile empty';el.dataset.x=x;el.dataset.y=y;el.setAttribute('role','gridcell');el.tabIndex=x===6&&y===6?0:-1;el.innerHTML='<canvas width="64" height="64"></canvas>';board.append(el);tileEls.push(el);}
function tileAt(x,y){return state.tiles.find(t=>t.x===x&&t.y===y);}
function icon(key,size=36){return `<canvas width="64" height="64" data-icon="${esc(key)}" style="width:${size}px;height:${size}px" aria-hidden="true"></canvas>`;}
function paintIcons(root=document){root.querySelectorAll('canvas[data-icon]').forEach(c=>{const ctx=c.getContext('2d');ctx.clearRect(0,0,64,64);drawIcon(ctx,c.dataset.icon,0,0,64);});}
function offerCanvas(offer,rot=0){const cells=rotateCells(offer.cells,rot);return `<canvas width="120" height="80" data-offer="${esc(offer.id)}" data-rotation="${rot}" aria-hidden="true"></canvas>`;}
function paintOffers(){panel.querySelectorAll('canvas[data-offer]').forEach(c=>{const o=state.offers.find(o=>String(o.id)===c.dataset.offer);if(!o)return;const cells=rotateCells(o.cells,Number(c.dataset.rotation));const w=Math.max(...cells.map(t=>t.x))+1,h=Math.max(...cells.map(t=>t.y))+1,s=Math.min(27,110/w,74/h);const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;for(const t of cells)drawTerrain(ctx,t.terrain,(120-w*s)/2+t.x*s,(80-h*s)/2+t.y*s,s,0);});}
function notify(message){if(dialog.open){let notice=dialog.querySelector('.dialog-notice');if(!notice){notice=document.createElement('p');notice.className='dialog-notice';notice.setAttribute('role','status');dialog.append(notice);}notice.textContent=message;}$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function save(){const result=writeSave(storage,state);unsaved=!result.ok;$('#records').textContent=unsaved?'未保存':'存档';if(!result.ok)notify(result.reason);return result;}
function act(fn,...args){if(blocked)return false;const result=fn(state,...args);if(!result.ok){notify(result.reason||'暂时不能这样操作');return false;}save();return true;}
function setTab(next){tab=next;selection=null;anchor=null;rotation=0;if(next!=='build')selectedTile=null;render();}
function levelData(){return {name:Rules.LEVELS[state.level].name,next:Rules.LEVELS?.[state.level+1]};}
function nextGoal(){const levels=Rules.LEVELS;if(Array.isArray(levels)){return levels.find(l=>(l.level??l.id)>state.level);}if(levels)return levels[state.level+1];return null;}
function goalText(){const g=nextGoal();if(!g)return state.level>=5?'继续扩建你的王国':'发展人口与学识，解锁新建筑';const pop=g.population??g.minPopulation??g.requiredPopulation??0,k=g.knowledge??g.minKnowledge??g.requiredKnowledge??0;return `人口 ${state.population}/${pop} · 学识 ${state.knowledge}/${k}`;}
function renderHud(){const f=forecast(state);$('#records').textContent=unsaved?'未保存':'存档';$('#season').textContent=`第 ${Math.floor((state.turn-1)/4)+1} 年 · ${seasonNames[(state.turn-1)%4]}`;const stats=[['gold',state.gold,`金币 ${signed(f.gold)}`],['food',state.food,`粮食 ${signed(f.food)}`],['wood',state.wood,`木材 ${signed(f.wood)}`],['population',state.population,`人口 / ${f.capacity}`],['happiness',state.happiness,'幸福']];$('#resources').innerHTML=stats.map(([key,value,label])=>`<div class="resource ${['food','gold','wood'].includes(key)&&f[key]<0?'negative':''}" aria-label="${label}，当前${value}">${icon(key,28)}<div><strong>${value}</strong><small>${label}</small></div></div>`).join('');$('#milestone').innerHTML=`${esc(levelData().name)} · ${state.tiles.length} 格领土<small>${esc(goalText())}</small>`;$('#turn-preview').innerHTML=`下季收入 <strong>${signed(f.gold)}</strong> 金币<br>粮食 ${signed(f.food)} · 学识 ${signed(f.knowledge)}`;$('#next-turn').disabled=!!selection||blocked;paintIcons($('.hud'));}
function drawBoard(){const map=new Map(state.tiles.map(t=>[`${t.x},${t.y}`,t]));let ghosts=[];let valid=true;if(selection?.kind==='land'&&anchor){ghosts=rotateCells(state.offers[selection.index].cells,rotation).map(c=>({...c,x:c.x+anchor.x,y:c.y+anchor.y}));valid=canPlaceLand(state,selection.index,anchor.x,anchor.y,rotation).ok;}for(const el of tileEls){const x=+el.dataset.x,y=+el.dataset.y,t=map.get(`${x},${y}`),g=ghosts.find(c=>c.x===x&&c.y===y);const canvas=el.firstElementChild,ctx=canvas.getContext('2d');ctx.clearRect(0,0,64,64);ctx.imageSmoothingEnabled=false;el.className='tile'+(t?' owned':' empty')+(selection?' placing':'');el.querySelector('.level')?.remove();if(t){drawTerrain(ctx,t.terrain,0,0,64,x+y*14);if(t.building){drawBuilding(ctx,t.building,0,0,64,t.level);if(t.level>1){const level=document.createElement('span');level.className='level';level.textContent='ⅡⅢ'[t.level-2];el.append(level);}}}if(g){ctx.globalAlpha=t?.building?.55:.85;drawTerrain(ctx,g.terrain,0,0,64,0);ctx.globalAlpha=1;el.classList.add(valid?'ghost':'invalid');}if(selection?.kind==='building'&&anchor?.x===x&&anchor?.y===y){ctx.globalAlpha=.8;drawBuilding(ctx,selection.type,0,0,64,1);ctx.globalAlpha=1;el.classList.add(buildReason(x,y)?'invalid':'ghost');}if(!selection&&selectedTile?.x===x&&selectedTile?.y===y)el.classList.add('selected');el.setAttribute('aria-label',`${x+1}列${y+1}行，${t?TERRAIN[t.terrain].name+(t.building?'，'+BUILDINGS[t.building].name+' '+t.level+'级':'，空地'):'未购土地'}`);}}
function findLandAnchor(index){let options=[];for(let y=0;y<14;y++)for(let x=0;x<14;x++)if(canPlaceLand(state,index,x,y,rotation).ok)options.push({x,y,d:Math.abs(x-6)+Math.abs(y-6)});options.sort((a,b)=>a.d-b.d);return options[0]?{x:options[0].x,y:options[0].y}:{x:8,y:5};}
function buildReason(x,y){const t=tileAt(x,y),b=BUILDINGS[selection.type];if(!t)return'先购买这块土地';if(t.building)return'这里已经有建筑';if(!b.terrains.includes(t.terrain))return`需要${b.terrains.map(k=>TERRAIN[k].name).join('或')}`;if(state.gold<b.cost)return'金币不足';if(state.wood<(b.woodCost||0))return'木材不足';return '';}
function renderPlacement(){const land=selection.kind==='land',b=land?state.offers[selection.index]:BUILDINGS[selection.type];let reason=anchor?(land?canPlaceLand(state,selection.index,anchor.x,anchor.y,rotation).reason:buildReason(anchor.x,anchor.y)):'点地图选择位置';const ok=anchor&&(land?canPlaceLand(state,selection.index,anchor.x,anchor.y,rotation).ok:!reason);panel.innerHTML=`<div class="selection"><div class="preview-title">${land?offerCanvas(b,rotation):icon(selection.type,52)}<div><h3>${esc(b.name)}</h3><p>${b.cost} 金币${b.woodCost?' · '+b.woodCost+' 木材':''}</p></div></div>${land?'':`<p>${esc(b.description)}</p>`}<p class="placement-reason ${!ok?'bad':''}">${ok?'位置合适，确认后扣款':esc(reason||'换一个位置试试')}</p><div class="actions"><button id="cancel-placement">取消</button>${land?'<button id="rotate">旋转 ↻</button>':''}<button id="confirm-placement" class="primary" ${ok?'':'disabled'}>${land?'买下并拼入':'确认建造'}</button></div></div>`;$('#cancel-placement').onclick=()=>{selection=null;anchor=null;render();centerOn();};if(land)$('#rotate').onclick=()=>{rotation=(rotation+1)%4;render();};$('#confirm-placement').onclick=()=>{const done=land?act(placeLand,selection.index,anchor.x,anchor.y,rotation):act(build,selection.type,anchor.x,anchor.y);if(done){const name=b.name;selection=null;anchor=null;selectedTile=null;render();notify(land?`${name}已拼入领土`:`${name}建造完成`);}};$('#hint').textContent=land?'点地图调整位置，也可以旋转':'点一格合适的空地';}
function renderLand(){if(state.landBought){panel.innerHTML='<div class="empty-message">本季的新土地已购入。<br>在空地上建造，或进入下一季。</div><div class="actions"><button id="go-build" class="primary">建造建筑</button></div>';$('#go-build').onclick=()=>setTab('build');$('#hint').textContent='拖动地图查看领土';return;}const price=5+state.rerolls*5;panel.innerHTML=`<div class="panel-heading"><span>本季选一块土地</span><button id="reroll" ${state.gold<price?'disabled':''}>刷新 · ${price} 金</button></div><div class="offers">${state.offers.map((o,i)=>`<button class="offer" data-offer-index="${i}" ${state.gold<o.cost?'disabled':''}>${offerCanvas(o)}<div><strong>${esc(o.name)}</strong><small>${o.cells.length} 格土地</small><div class="price">${o.cost} 金币</div></div></button>`).join('')}</div>`;panel.querySelectorAll('[data-offer-index]').forEach(el=>el.onclick=()=>{selection={kind:'land',index:+el.dataset.offerIndex};rotation=0;anchor=findLandAnchor(selection.index);render();revealAnchor();});$('#reroll').onclick=()=>{if(act(reroll)){render();notify('新地块已到达');}};$('#hint').textContent=state.turn===1?'选一块新土地，拼到王国旁边':'拖动地图 · 每季可买一块土地';}
function buildButtons(terrain){return Object.entries(BUILDINGS).filter(([key,b])=>key!=='hall'&&(!terrain||b.terrains.includes(terrain))).map(([key,b])=>{const locked=state.level<b.unlock;return`<button class="building" data-build="${key}" ${locked||state.gold<b.cost||state.wood<(b.woodCost||0)?'disabled':''}>${icon(key,44)}<span><strong>${esc(b.name)}</strong><small>${locked?`城镇${b.unlock}级`:`${b.cost}金${b.woodCost?' '+b.woodCost+'木':''}`}</small></span></button>`;}).join('');}
function renderBuild(){const t=selectedTile&&tileAt(selectedTile.x,selectedTile.y);if(t?.building){const b=BUILDINGS[t.building],cost=Rules.upgradeCost?Rules.upgradeCost(t):null;const gc=cost?.gold??cost??0,wc=cost?.wood??0;panel.innerHTML=`<div class="inspect-heading">${icon(t.building,56)}<div><h3>${esc(b.name)} · ${t.level}级</h3><p>${esc(TERRAIN[t.terrain].name)} · ${t.x+1}列${t.y+1}行</p></div></div><p class="tile-description">${esc(b.description)}</p><div class="actions"><button id="unselect">返回</button><button id="upgrade" class="primary" ${t.level>=3||state.gold<gc||state.wood<wc?'disabled':''}>${t.level>=3?'已满级':`升级 ${gc}金${wc?' '+wc+'木':''}`}</button>${t.building!=='hall'?'<button id="demolish">拆除</button>':''}</div>`;$('#unselect').onclick=()=>{selectedTile=null;render();};$('#upgrade').onclick=()=>{if(act(upgrade,t.x,t.y)){render();notify('建筑升级完成');}};if($('#demolish'))$('#demolish').onclick=()=>showDialog(`<h2>拆除${esc(b.name)}？</h2><p>土地保留，返还部分金币；重新建造需要再次付费。</p><button id="confirm-demolish" class="danger">确认拆除</button>`,()=>{$('#confirm-demolish').onclick=()=>{if(act(demolish,t.x,t.y)){dialog.close();render();notify('建筑已拆除，土地保留');}};});}else{panel.innerHTML=`${t?`<div class="panel-heading"><span>${esc(TERRAIN[t.terrain].name)} · 可建建筑</span><button id="all-buildings">查看全部</button></div>`:''}<div class="buildings">${buildButtons(t?.terrain)}</div>`;if($('#all-buildings'))$('#all-buildings').onclick=()=>{selectedTile=null;render();};panel.querySelectorAll('[data-build]').forEach(el=>el.onclick=()=>{selection={kind:'building',type:el.dataset.build};anchor=t?{x:t.x,y:t.y}:null;render();});}$('#hint').textContent=t?.building?'选中建筑可升级或拆除':'点空地查看适合这里的建筑';}

function renderRealm(){const f=forecast(state);panel.innerHTML=`<div class="realm-stats"><div><strong>${state.population}/${f.capacity}</strong>居民 / 住房</div><div><strong>${state.knowledge}</strong>学识 ${signed(f.knowledge)}</div><div><strong>${state.happiness}</strong>幸福 → ${f.happiness}</div><div><strong>${f.defense}</strong>防务</div></div><div class="policy" aria-label="国家政策">${[['balanced','均衡'],['growth','安居'],['trade','商贸']].map(([id,name])=>`<button data-policy="${id}" class="${state.policy===id?'active':''}" aria-pressed="${state.policy===id}">${name}</button>`).join('')}</div><p class="policy-description">${esc(Rules.POLICIES[state.policy].description)}</p><div class="separator"></div><p class="goal-copy">${(f.effects||[]).map(esc).join('<br>')}</p><ul class="log">${state.log.slice(-5).reverse().map(item=>`<li>${esc(typeof item==='string'?item:item.message??item.text??JSON.stringify(item))}</li>`).join('')}</ul>`;panel.querySelectorAll('[data-policy]').forEach(el=>el.onclick=()=>{if(act(setPolicy,el.dataset.policy)){render();notify('国家政策已调整');}});$('#hint').textContent='点地图上的建筑可查看详情';}
function render(){renderHud();document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',b.dataset.tab===tab));if(selection)renderPlacement();else if(tab==='land')renderLand();else if(tab==='build')renderBuild();else renderRealm();paintIcons(panel);paintOffers();drawBoard();}
function centerOn(x=6.5,y=6.5){viewport.scrollLeft=150+x*cell-viewport.clientWidth/2;viewport.scrollTop=150+y*cell-viewport.clientHeight/2;}
function revealAnchor(){if(!anchor)return;const cells=selection?.kind==='land'?rotateCells(state.offers[selection.index].cells,rotation):[{x:0,y:0}];const w=Math.max(...cells.map(t=>t.x))+1,h=Math.max(...cells.map(t=>t.y))+1;centerOn(anchor.x+w/2,anchor.y+h/2);}
function chooseTile(x,y){if(blocked)return;if(selection){anchor={x,y};render();}else{const t=tileAt(x,y);if(!t){if(state.landBought){notify('下一季可以买更多土地');return;}tab='land';selectedTile=null;render();notify('先从三块土地中选择一块');}else{selectedTile={x,y};tab='build';render();}}}
let drag=null;
viewport.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={x:e.clientX,y:e.clientY,left:viewport.scrollLeft,top:viewport.scrollTop,id:e.pointerId,moved:false,tile:e.target.closest('.tile')};});
viewport.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>7){drag.moved=true;viewport.classList.add('dragging');viewport.setPointerCapture(e.pointerId);}if(drag.moved){viewport.scrollLeft=drag.left-dx;viewport.scrollTop=drag.top-dy;}});
viewport.addEventListener('pointerup',e=>{if(!drag)return;const tapped=drag.moved?null:drag.tile;viewport.classList.remove('dragging');if(viewport.hasPointerCapture(e.pointerId))viewport.releasePointerCapture(e.pointerId);drag=null;if(tapped)chooseTile(+tapped.dataset.x,+tapped.dataset.y);});
viewport.addEventListener('pointercancel',()=>{drag=null;viewport.classList.remove('dragging');});
board.addEventListener('click',e=>{if(e.detail!==0)return;const el=e.target.closest('.tile');if(el)chooseTile(+el.dataset.x,+el.dataset.y);});
board.addEventListener('keydown',e=>{const el=e.target.closest('.tile');if(!el)return;const dirs={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]};if(dirs[e.key]){e.preventDefault();const [dx,dy]=dirs[e.key],x=Math.max(0,Math.min(13,+el.dataset.x+dx)),y=Math.max(0,Math.min(13,+el.dataset.y+dy));tileEls.forEach(t=>t.tabIndex=-1);const target=tileEls[y*14+x];target.tabIndex=0;target.focus({preventScroll:true});centerOn(x+.5,y+.5);}if(e.key==='Escape'){selection=null;anchor=null;render();}});
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));
$('#center').onclick=()=>centerOn();$('#milestone').onclick=()=>setTab('realm');
function zoom(delta){const x=(viewport.scrollLeft+viewport.clientWidth/2-150)/cell,y=(viewport.scrollTop+viewport.clientHeight/2-150)/cell;cell=Math.max(44,Math.min(88,cell+delta));board.style.setProperty('--cell',cell+'px');centerOn(x,y);$('#zoom-out').disabled=cell===44;$('#zoom-in').disabled=cell===88;}
$('#zoom-in').onclick=()=>zoom(8);$('#zoom-out').onclick=()=>zoom(-8);
function showDialog(html,bind){dialog.querySelector('.dialog-notice')?.remove();$('#dialog-body').innerHTML=html;$('#close-dialog').textContent='继续经营';if(!dialog.open)dialog.showModal();bind?.();paintIcons(dialog);}
$('#close-dialog').onclick=()=>{if(blocked){notify('请先处理原存档，避免覆盖进度');return;}dialog.close();};
dialog.addEventListener('cancel',e=>{if(blocked)e.preventDefault();});
$('#next-turn').onclick=()=>{const before=structuredClone(state);if(!act(nextTurn))return;selectedTile=null;render();showDialog(`<h2>第 ${Math.floor((before.turn-1)/4)+1} 年 · ${seasonNames[(before.turn-1)%4]}季结算</h2><div class="report">${[['金币','gold'],['粮食','food'],['木材','wood'],['居民','population']].map(([label,key])=>`<div>${label}<strong>${signed(state[key]-before[key])}</strong></div>`).join('')}</div><p>${esc(typeof state.log.at(-1)==='string'?state.log.at(-1):state.log.at(-1)?.message??'新的季度开始了，土地市场已经刷新。')}</p>${state.level>before.level?`<p><strong>发展为${esc(levelData().name)}！新的建筑已解锁。</strong></p>`:''}`);};
function download(text,name){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function showRecords(){showDialog(`<h2>王国存档</h2><p>${unsaved?'最近的改动还未保存，请立即导出备份。':'进度自动保存在当前浏览器；更换浏览器前请导出备份。'}</p><div class="save-actions"><button id="export">导出存档</button><button id="import">导入存档</button><button id="restart">新王国</button></div><input type="file" id="file-input" accept=".json,application/json"><div class="separator"></div><p>每季选一块土地，旋转后拼到领土旁。点空地建造，点建筑升级。拖动地图查看四周。</p><p>水边农田、住宅旁的市场等搭配会提升收益；在国政中查看季节影响与发展条件。</p>`,()=>{$('#export').onclick=()=>download(JSON.stringify(state,null,2),'拼土王国-第'+state.turn+'季.json');$('#import').onclick=()=>$('#file-input').click();$('#file-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const result=validateSave(JSON.parse(await file.text()));if(!result.ok){notify(result.reason);return;}showDialog('<h2>替换当前王国？</h2><p>已检查导入存档。确认后替换当前进度，并在本浏览器保留一份替换前备份。</p><button id="confirm-import">确认导入</button>',()=>{$('#confirm-import').onclick=()=>{const result2=replaceSave(storage,result.state);if(!result2.ok){notify(result2.reason);return;}state=result.state;unsaved=false;selection=null;selectedTile=null;tab='land';dialog.close();render();centerOn();notify('存档导入成功');};});}catch{notify('文件不是可用的王国存档，原进度保留。');}};$('#restart').onclick=()=>showDialog('<h2>开始新王国？</h2><p>当前进度会替换。建议先导出存档；本浏览器也会保留一份替换前备份。</p><button id="confirm-restart" class="danger">确认开始新王国</button>',()=>{$('#confirm-restart').onclick=()=>{const next=createGame(Date.now()>>>0),result=replaceSave(storage,next);if(!result.ok){notify(result.reason);return;}state=next;selection=null;selectedTile=null;tab='land';unsaved=false;dialog.close();render();centerOn();};});});}
$('#records').onclick=showRecords;
await loadArt();render();requestAnimationFrame(()=>centerOn());
if(blocked){showDialog(`<h2>原存档暂时无法载入</h2><p>${esc(loaded.reason)}。原件仍保留，尚未被覆盖。</p><div class="save-actions"><button id="export-original">导出原件</button><button id="recover-new">备份并建立新王国</button></div>`,()=>{$('#export-original').onclick=()=>{try{download(storage.getItem(SAVE_KEY)||'','拼土王国-原存档.json');}catch{notify('当前浏览器不允许读取存档');}};$('#recover-new').onclick=()=>{const result=replaceSave(storage,state);if(!result.ok){notify(result.reason);return;}blocked=false;dialog.close();render();};});$('#close-dialog').textContent='原进度已保留';}else if(!loaded.state)save();
new ResizeObserver(()=>{if(!drag)centerOn();}).observe(viewport);
